import java.lang.annotation.*;
import java.lang.reflect.*;
import java.util.*;

public class Main {
    static String buatSql(Class<?> kelas) {
        String tabel = kelas.getAnnotation(Tabel.class).value();
        List<String> kolom = new ArrayList<>();
        for (Field f : kelas.getDeclaredFields()) {
            Kolom k = f.getAnnotation(Kolom.class);
            kolom.add(k == null || k.nama().isEmpty() ? f.getName() : k.nama());
        }
        return "SELECT " + String.join(", ", kolom) + " FROM " + tabel;
    }

    public static void main(String[] args) throws Exception {
        Tabel t = Tugas.class.getAnnotation(Tabel.class);
        System.out.println("Tabel: " + t.value());

        for (Field f : Tugas.class.getDeclaredFields()) {
            Kolom k = f.getAnnotation(Kolom.class);
            if (k == null) {
                System.out.println(f.getName() + ": tanpa @Kolom");
            } else {
                String nama = k.nama().isEmpty() ? f.getName() : k.nama();
                System.out.println(f.getName() + " -> " + nama + (k.wajib() ? " (wajib)" : ""));
            }
        }

        System.out.println(Tugas.class.isAnnotationPresent(Tabel.class) + " " + String.class.isAnnotationPresent(Tabel.class));
        System.out.println(buatSql(Tugas.class));
    }
}

